/**
 * @distilled.cloud/caddy — Caddy admin API SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy model in
 * `.generated-specs` (hand-authored by `scripts/convert.ts` — Caddy publishes
 * no machine-readable spec for its admin API; see `docs/provenance.md`).
 * Everything else in this folder is hand-written.
 *
 * One module, `admin` — Caddy's admin API has a single namespace, unlike a
 * multi-tag REST API.
 *
 * @example
 * ```ts
 * import * as Caddy from "@distilled.cloud/caddy";
 *
 * const config = yield* Caddy.Services.admin.getConfig({ path: "apps/http" });
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  CaddyProtocol,
  type CaddyOpError,
  type CaddyOpContext,
} from "./protocol.ts";
export * as Retry from "./retry.ts";
export * as Services from "./services/index.ts";
